mapper.sql:
AND stat_row.tenant_id=#{tenantId}
AND stat_row.task_type=#{taskType}

    AND stat_row.sender_country_iso2=#{senderCountryIso2}


    AND stat_row.recipient_country_iso2=#{recipientCountryIso2}

AND stat_row.account_type=#{accountType}

    AND stat_row.sender_device_os=#{senderDeviceOs}


    AND stat_row.is_short_link_enabled=#{shortLinkEnabled}

AND recipient.tenant_id=#{tenantId}
AND recipient.submitted_at>=#{startAt}
AND recipient.submitted_at<#{endExclusiveAt}
AND task.task_type=#{taskType}

    AND COALESCE(recipient.sender_country_iso2_snapshot,'ZZ')=#{senderCountryIso2}


    AND COALESCE(recipient.recipient_country_iso2_snapshot,'ZZ')=#{recipientCountryIso2}


    AND COALESCE(recipient.sender_account_type_snapshot,0)=#{accountType}


    AND COALESCE(recipient.sender_device_os_snapshot,0)=#{senderDeviceOs}


    AND task.is_short_link_enabled=#{shortLinkEnabled}

mapper.select:


        SELECT DISTINCT stat_row.sender_country_iso2, stat_row.recipient_country_iso2
        FROM hyperlink_stat_daily stat_row
        WHERE stat_row.stat_date BETWEEN #{statDateFrom} AND #{statDateTo}
          AND stat_row.tenant_id=#{tenantId}


        SELECT DISTINCT stat_row.sender_country_iso2, stat_row.recipient_country_iso2
        FROM hyperlink_stat_hourly stat_row
        WHERE stat_row.stat_hour_start_at>=#{startAt}
          AND stat_row.stat_hour_start_at<#{endExclusiveAt}
          AND stat_row.tenant_id=#{tenantId}


ORDER BY stat_row.sender_country_iso2, stat_row.recipient_country_iso2
